/bin/bash -c "python3 - <<'PY'
import math, itertools
expit=lambda x: 1/(1+math.exp(-x))
p={}
# Integrating U1 gives P(H,V)=(1/6,1/3,1/3,1/6).
for h,v,c,r,y in itertools.product([0,1],repeat=5):
 phv=1/6 if h==v else 1/3
 pr=expit(.75*h+.5*c)
 py=expit(-.5+2.5*v+1.75*c)
 p[h,v,c,r,y]=phv*.5*(pr if r else 1-pr)*(py if y else 1-py)
def mean_y(**cond):
 inds={'h':0,'v':1,'c':2,'r':3,'y':4}
 selected=[(k,pk) for k,pk in p.items() if all(k[inds[a]]==b for a,b in cond.items())]
 return sum(k[4]*pk for k,pk in selected)/sum(pk for k,pk in selected)
print('Under the stated simulation equations:')
for h in [0,1]: print(f'P(Y=1|H={h})={mean_y(h=h):.6f}')
for c in [0,1]:
 for r in [0,1]: print(f'P(Y=1|C={c},R={r})={mean_y(c=c,r=r):.6f}')
print('Always-positive expected accuracy:',mean_y())
print('Bayes accuracy from V,C:',sum(max(expit(-.5+2.5*v+1.75*c),1-expit(-.5+2.5*v+1.75*c)) for v,c in itertools.product([0,1],repeat=2))/4)
print('Reported bird splits sum:',2849+520+529)
print('Dense contingency cells for 5-valued attribute and 9-class outcome given 4 5-valued attributes:',5*9*5**4)
