from itertools import combinations
# Compare d-separations of the stated DAG and a compatible DAG where H causes V.
observed=('H','V','R','Y')
def independent(edges,a,b,condition):
 nodes=set(sum(([u,v] for u,v in edges),[]))
 parents={v:set() for v in nodes}
 for u,v in edges: parents[v].add(u)
 ancestors={a,b}|set(condition)
 todo=list(ancestors)
 while todo:
  for par in parents[todo.pop()]:
   if par not in ancestors:
    ancestors.add(par); todo.append(par)
 adj={v:set() for v in ancestors}
 for v in ancestors:
  ps=parents[v]&ancestors
  for u in ps: adj[u].add(v); adj[v].add(u)
  for u,w in combinations(ps,2): adj[u].add(w); adj[w].add(u)
 seen=set(condition); todo=[a]
 while todo:
  v=todo.pop()
  if v in seen: continue
  if v==b: return False
  seen.add(v); todo.extend(adj[v]-seen)
 return True
original=[('U','H'),('U','V'),('H','R'),('C','R'),('C','Y'),('V','Y')]
alternative=[('H','V'),('H','R'),('C','R'),('C','Y'),('V','Y')]
for name,edges in [('Original',original),('Alternative with H -> V -> Y',alternative)]:
 relations=[]
 for a,b in combinations(observed,2):
  rest=[v for v in observed if v not in (a,b)]
  for size in range(len(rest)+1):
   for condition in combinations(rest,size):
    if independent(edges,a,b,condition): relations.append(f'{a} independent {b} | {condition}')
 print(name,relations)
